window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-73e5e670b0c19f14"]={"versions": [{"id": "FIG-73e5e670b0c19f14", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodellausschnitt zur ECU-Konfiguration (BSW Parameter Definition) des RTE-Moduls innerhalb der AUTOSAR Classic Platform. Das Diagramm spezifiziert die Konfigurationsstruktur für die Aktivierungsmechanismen von RTE-Entitäten durch das Betriebssystem (<code>RteOsInteraction</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>RteOsInteraction</strong> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*): Übergeordneter Konfigurationscontainer. Enthält per Komposition (<code>+subContainer</code>) den Container <code>RteUsedOsActivation</code>.\n</li><li><strong>RteUsedOsActivation</strong> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..*): Beschreibt die konkrete vom RTE genutzte OS-Aktivierung. Enthält:\n<ul class=\"fig-list\"><li><strong>RteActivationOsTaskRef</strong> (<code>EcucReferenceDef</code>, Multiplizität 0..1, Rolle <code>+reference</code>): Referenziert per <code>+destination</code> den Zielcontainer <code>OsTask</code> (<code>EcucParamConfContainerDef</code>, 0..*, aus Paket <code>(from OS)</code>).\n</li><li><strong>RteActivationOsSchTblRef</strong> (<code>EcucReferenceDef</code>, Multiplizität 0..1, Rolle <code>+reference</code>): Referenziert per <code>+destination</code> den Zielcontainer <code>OsScheduleTable</code> (<code>EcucParamConfContainerDef</code>, 0..*, aus Paket <code>(from OS)</code>).\n</li><li><strong>RteActivationOsAlarmRef</strong> (<code>EcucReferenceDef</code>, Multiplizität 0..1, Rolle <code>+reference</code>): Referenziert per <code>+destination</code> den Zielcontainer <code>OsAlarm</code> (<code>EcucParamConfContainerDef</code>, 0..*, aus Paket <code>(from OS)</code>).\n</li><li><strong>RteExpectedTickDuration</strong> (<code>EcucFloatParamDef</code>, Multiplizität 1..1, Rolle <code>+parameter</code>): Fließkommaparameter mit Wertebereich <code>min = 0</code>, <code>max = INF</code>.\n</li><li><strong>RteExpectedActivationOffset</strong> (<code>EcucFloatParamDef</code>, Multiplizität 1..1, Rolle <code>+parameter</code>): Fließkommaparameter mit Wertebereich <code>min = 0</code>, <code>max = INF</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmodell zur Entwurfs- und Generierungszeit. Das Diagramm modelliert keine zeitlichen Abläufe oder Laufzeitsequenzen, sondern definiert die Parametrisierungsbeziehungen, mit denen die RTE-Generierung konfiguriert wird, um Aktivierungen über Tasks, Alarme oder Schedule-Tabellen des Betriebssystems aufzulösen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung für AUTOSAR-ECUC-Parametrisierungswerkzeuge und den RTE-Generator. <code>RteUsedOsActivation</code> bindet wahlweise Task-, Schedule-Table- oder Alarm-Referenzen an (Multiplizität jeweils 0..1), während die Timing-Parameter <code>RteExpectedTickDuration</code> und <code>RteExpectedActivationOffset</code> obligatorisch (1..1) im Wertebereich <code>[0, INF]</code> konfiguriert werden müssen. Die Zielentitäten verweisen normativ in die Betriebssystem-Konfiguration (<code>OsTask</code>, <code>OsScheduleTable</code>, <code>OsAlarm</code>).</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-d09db8af6941749d", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodellausschnitt zur ECU-Konfiguration (BSW Parameter Definition) des RTE-Moduls innerhalb der AUTOSAR Classic Platform. Das Diagramm spezifiziert die Konfigurationsstruktur für die Aktivierungsmechanismen von RTE-Entitäten durch das Betriebssystem (<code>RteOsInteraction</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>RteOsInteraction</strong> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*): Übergeordneter Konfigurationscontainer. Enthält per Komposition (<code>+subContainer</code>) den Container <code>RteUsedOsActivation</code>.\n</li><li><strong>RteUsedOsActivation</strong> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..*): Beschreibt die konkrete vom RTE genutzte OS-Aktivierung. Enthält:\n<ul class=\"fig-list\"><li><strong>RteActivationOsTaskRef</strong> (<code>EcucReferenceDef</code>, Multiplizität 0..1, Rolle <code>+reference</code>): Referenziert per <code>+destination</code> den Zielcontainer <code>OsTask</code> (<code>EcucParamConfContainerDef</code>, 0..*, aus Paket <code>(from OS)</code>).\n</li><li><strong>RteActivationOsSchTblRef</strong> (<code>EcucReferenceDef</code>, Multiplizität 0..1, Rolle <code>+reference</code>): Referenziert per <code>+destination</code> den Zielcontainer <code>OsScheduleTable</code> (<code>EcucParamConfContainerDef</code>, 0..*, aus Paket <code>(from OS)</code>).\n</li><li><strong>RteActivationOsAlarmRef</strong> (<code>EcucReferenceDef</code>, Multiplizität 0..1, Rolle <code>+reference</code>): Referenziert per <code>+destination</code> den Zielcontainer <code>OsAlarm</code> (<code>EcucParamConfContainerDef</code>, 0..*, aus Paket <code>(from OS)</code>).\n</li><li><strong>RteExpectedTickDuration</strong> (<code>EcucFloatParamDef</code>, Multiplizität 1..1, Rolle <code>+parameter</code>): Fließkommaparameter mit Wertebereich <code>min = 0</code>, <code>max = INF</code>.\n</li><li><strong>RteExpectedActivationOffset</strong> (<code>EcucFloatParamDef</code>, Multiplizität 1..1, Rolle <code>+parameter</code>): Fließkommaparameter mit Wertebereich <code>min = 0</code>, <code>max = INF</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmodell zur Entwurfs- und Generierungszeit. Das Diagramm modelliert keine zeitlichen Abläufe oder Laufzeitsequenzen, sondern definiert die Parametrisierungsbeziehungen, mit denen die RTE-Generierung konfiguriert wird, um Aktivierungen über Tasks, Alarme oder Schedule-Tabellen des Betriebssystems aufzulösen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung für AUTOSAR-ECUC-Parametrisierungswerkzeuge und den RTE-Generator. <code>RteUsedOsActivation</code> bindet wahlweise Task-, Schedule-Table- oder Alarm-Referenzen an (Multiplizität jeweils 0..1), während die Timing-Parameter <code>RteExpectedTickDuration</code> und <code>RteExpectedActivationOffset</code> obligatorisch (1..1) im Wertebereich <code>[0, INF]</code> konfiguriert werden müssen. Die Zielentitäten verweisen normativ in die Betriebssystem-Konfiguration (<code>OsTask</code>, <code>OsScheduleTable</code>, <code>OsAlarm</code>).</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-73e5e670b0c19f14", "to": "FIG-d09db8af6941749d", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
